pub proof fn wf1<T>(spec: TempPred<T>, next: ActionPred<T>, forward: ActionPred<T>, p: StatePred<T>, q: StatePred<T>)
    requires
        forall |s, s_prime: T| p(s) && #[trigger] next(s, s_prime) ==> p(s_prime) || q(s_prime),
        forall |s, s_prime: T| p(s) && #[trigger] next(s, s_prime) && forward(s, s_prime) ==> q(s_prime),
        forall |s: T| #[trigger] p(s) ==> enabled(forward)(s),
        spec.entails(always(lift_action(next))),
        spec.entails(weak_fairness(forward)),
    ensures spec.entails(lift_state(p).leads_to(lift_state(q))),
{
    let p_temp = lift_state(p);
    let q_temp = lift_state(q);
    let next_temp = lift_action(next);
    let forward_temp = lift_action(forward);

    // Proof of condition 1: spec.entails(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))))
    assert(spec.entails(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))))) by {
        assert(valid(spec.implies(always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp))))))) by {
            assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
                always(p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))).satisfied_by(ex) by {
                    assert forall |i: nat| #[trigger] (p_temp.and(next_temp).implies(later(p_temp).or(later(q_temp)))).satisfied_by(ex.suffix(i)) by {
                        if p_temp.and(next_temp).satisfied_by(ex.suffix(i)) {
                            // p holds at head of ex.suffix(i), next holds at head/head_next
                            let s = ex.suffix(i).head();
                            let s_prime = ex.suffix(i).head_next();
                            assert(p(s));
                            assert(next(s, s_prime));
                            // By hypothesis 1: p(s') || q(s')
                            assert(p(s_prime) || q(s_prime));
                            // s' = head of ex.suffix(i).suffix(1)
                            // later(p_temp) means p_temp.satisfied_by(ex.suffix(i).suffix(1))
                            // which means p(ex.suffix(i).suffix(1).head()) = p(s')
                            suffix_plus_one(ex, i);
                        }
                    };
            };
        };
    };

    // Proof of condition 2: spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))))
    assert(spec.entails(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))))) by {
        assert(valid(spec.implies(always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp)))))) by {
            assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
                always(p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))).satisfied_by(ex) by {
                    assert forall |i: nat| #[trigger] (p_temp.and(next_temp).and(forward_temp).implies(later(q_temp))).satisfied_by(ex.suffix(i)) by {
                        if p_temp.and(next_temp).and(forward_temp).satisfied_by(ex.suffix(i)) {
                            let s = ex.suffix(i).head();
                            let s_prime = ex.suffix(i).head_next();
                            assert(p(s));
                            assert(next(s, s_prime));
                            assert(forward(s, s_prime));
                            assert(q(s_prime));
                            suffix_plus_one(ex, i);
                        }
                    };
            };
        };
    };

    // Proof of condition 3: spec.entails(always(next_temp)) - given directly
    // already given: spec.entails(always(lift_action(next)))

    // Proof of condition 4: spec.entails(always(p_temp).leads_to(forward_temp))
    // This follows from weak_fairness(forward) + hypothesis 3 (p => enabled(forward))
    assert(spec.entails(always(p_temp).leads_to(forward_temp))) by {
        // always(p_temp).leads_to(forward_temp) = always(always(p_temp).implies(eventually(forward_temp)))
        // We need: spec |= always(always(p_temp).implies(eventually(forward_temp)))
        // i.e., for each execution ex satisfying spec, for each i,
        //   if always(p_temp).satisfied_by(ex.suffix(i)) then eventually(forward_temp).satisfied_by(ex.suffix(i))
        // From always(p_temp): p holds at all positions from i onwards
        // From weak_fairness(forward): always(enabled(forward)).leads_to(lift_action(forward))
        //   = always(always(enabled_temp).implies(eventually(forward_temp)))
        // We need to show always(enabled_temp) from always(p_temp) using hypothesis 3
        let enabled_temp = lift_state(enabled(forward));

        assert(valid(spec.implies(always(p_temp).leads_to(forward_temp)))) by {
            assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies
                always(p_temp).leads_to(forward_temp).satisfied_by(ex) by {
                    // leads_to unfolds to: always(always(p_temp).implies(eventually(forward_temp)))
                    assert forall |i: nat| #[trigger] always(p_temp).implies(eventually(forward_temp)).satisfied_by(ex.suffix(i)) by {
                        if always(p_temp).satisfied_by(ex.suffix(i)) {
                            // From hypothesis 3: p(s) => enabled(forward)(s)
                            // always(p_temp) at ex.suffix(i) means: forall j, p(ex.suffix(i).suffix(j).head())
                            // So enabled(forward) holds at all states from i onwards
                            // i.e., always(enabled_temp) at ex.suffix(i)
                            assert(always(enabled_temp).satisfied_by(ex.suffix(i))) by {
                                assert forall |j: nat| #[trigger] enabled_temp.satisfied_by(ex.suffix(i).suffix(j)) by {
                                    // p holds here, so enabled(forward) holds
                                    let s = ex.suffix(i).suffix(j).head();
                                    assert(p(s)); // from always(p_temp)
                                    assert(enabled(forward)(s)); // from hypothesis 3
                                };
                            };
                            // Now use weak_fairness(forward):
                            // weak_fairness(forward).satisfied_by(ex) since spec |= weak_fairness(forward)
                            assert(weak_fairness(forward).satisfied_by(ex));
                            weak_fairness_unfold(ex, forward);
                            // This gives: forall k, always(enabled_temp).implies(eventually(forward_temp)).satisfied_by(ex.suffix(k))
                            // In particular for k = i
                            assert(always(enabled_temp).implies(eventually(forward_temp)).satisfied_by(ex.suffix(i)));
                            implies_apply(ex.suffix(i), always(enabled_temp), eventually(forward_temp));
                        }
                    };
            };
        };
    };

    wf1_variant_temp(spec, next_temp, forward_temp, p_temp, q_temp);
}

