                        let s_prime = ex.suffix(i).head_next();
                        assert(p(s));
                        assert(next(s, s_prime));
                        assert(forward(s, s_prime));
                        assert(q(s_prime));
                        assert(ex.suffix(i).suffix(1).head() == s_prime);
